def solve_sgp_backtracking_v3(n_golfers, n_weeks, n_groups, group_size):
    # x[w][p] = group_id
    # We can use a simple backtracking with pruning

    schedule = [[-1 for _ in range(n_golfers)] for _ in range(n_weeks)]

    # Precompute pairs
    # This is not needed if we check on the fly

    def backtrack(w, p):
        if w == n_weeks:
            return True
        if p == n_golfers:
            return backtrack(w + 1, 0)

        # Try assigning golfer p to a group g
        # Which groups are valid?
        # 1. Group g has < group_size players
        # 2. No player in group g has played with p before

        # To speed up, we can try groups in a random order
        groups = list(range(n_groups))
        random.shuffle(groups)

        for g in groups:
            # Check if group g is valid
            # 1. Count players in group g
            count = 0
            for i in range(p):
                if schedule[w][i] == g:
                    count += 1
            if count >= group_size:
                continue

            # 2. Check if any player in group g has played with p
            can_add = True
            for i in range(p):
                if schedule[w][i] == g:
                    # Check if i and p have played together before
                    for prev_w in range(w):
                        if schedule[prev_w][i] == schedule[prev_w][p]:
                            can_add = False
                            break
                if not can_add:
                    break

            if can_add:
                schedule[w][p] = g
                if backtrack(w, p + 1):
                    return True
                schedule[w][p] = -1
        return False

    if backtrack(0, 0):
        # Flatten the schedule
        result = []
        for w in range(n_weeks):
            for p in range(n_golfers):
                result.append(schedule[w][p])
